    visited = set()  # visited nodes to avoid cycles
    path_stack = [(start, [start])]  # stack of tuples (node, path)

    while path_stack:
        (current, path) = path_stack.pop()
        if current not in visited:
            visited.add(current)
            if current == goal:
                return path

            # Add unvisited neighbors to the stack
            unvisited_neighbors = [neighbor for neighbor in graph[current] if neighbor not in visited]
            for neighbor in unvisited_neighbors:
                path_stack.append((neighbor, path + [neighbor]))

    return None
