def find_path(graph, start, goal):
    # Helper function to perform DFS and keep track of visited nodes
    def dfs(graph, start, goal, visited_nodes, path):
        visited_nodes.add(start)
        path.append(start)

        if start == goal:
            return path

        for neighbour in graph.get(start, []):
            if neighbour not in visited_nodes:
                result = dfs(graph, neighbour, goal, visited_nodes, path)
                if result is not None:
                    return result

        path.pop()
        visited_nodes.remove(start)
        return None

    visited = set()
    return dfs(graph, start, goal, visited, [])
